def svg(nodes):
    w=max(560,len(nodes)*112); out=f'<svg viewBox="0 0 {w} 120" role="img" aria-label="Signal map">'
    out+='<defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#94a3b8"/></marker></defs>'
    for i,n in enumerate(nodes):
        x=10+i*112
        if i: out+=f'<line x1="{x-8}" y1="60" x2="{x+4}" y2="60" stroke="#94a3b8" marker-end="url(#arr)"/>'
        out+=f'<rect x="{x}" y="35" width="92" height="50" rx="7" fill="#{"e9fff4" if i==len(nodes)-1 else "ffffff"}" stroke="{"#01dc82" if i==len(nodes)-1 else "#cbd5e1"}"/><text x="{x+46}" y="57" text-anchor="middle" class="label">{html.escape(n[:14])}</text><text x="{x+46}" y="73" text-anchor="middle" class="label">{html.escape(n[14:28])}</text>'
    return out+'</svg>'

def page(title, lane, readout, cards, matrix, actions):
    body=f'<header><div class="wordmark">{LOGO}<span>Buildn</span></div><div class="badges"><span class="badge good">Daily ingest</span><span class="badge">{DATE}</span></div><h1>Daily Ingest Dossier — {html.escape(lane)}</h1><p class="dek">{html.escape(readout)}</p></header><section class="card"><h2>Signal map</h2><div class="diagram">{svg([c["short"] for c in cards])}</div><p>Read left to right: capability arrives, becomes operational, then needs a measurement or boundary.</p></section>'
    for c in cards:
        body+=f'<article class="card" id="{c["id"]}"><h2>{html.escape(c["title"])}</h2><div class="badges"><span class="badge good">{html.escape(c["type"])}</span><span class="badge">{html.escape(c["date"])}</span></div><ul class="facts"><li>Source: <a href="{c["url"]}">{html.escape(c["source"])}</a></li><li>Use: {html.escape(c["use"])}</li></ul><p><strong>What it is.</strong> {html.escape(c["what"])}</p><p><strong>Why it matters.</strong> {html.escape(c["why"])}</p><p><strong>Buildn/client use.</strong> {html.escape(c["buildn"])}</p><p><strong>Caveat.</strong> {html.escape(c["caveat"])}</p><ul class="wins"><li>Open the primary source</li><li>Test one bounded workflow</li><li>Record evidence and cost</li></ul></article>'
    body+='<section class="card"><h2>Use-case matrix</h2><table class="matrix"><thead><tr><th>Signal</th><th>Buildn OS</th><th>Client work</th><th>Agent workflow</th><th>Personal leverage</th></tr></thead><tbody>'
    for r in matrix: body+=f'<tr>{"".join(f"<td>{html.escape(x)}</td>" for x in r)}</tr>'
    body+='</tbody></table></section><section class="card top"><h2>Top actions</h2><ol>'+''.join(f'<li>{html.escape(a)}</li>' for a in actions)+'</ol></section><section class="card"><h2>Source trail</h2><ol class="source-list">'+''.join(f'<li><a href="{c["url"]}">{html.escape(c["title"])}</a></li>' for c in cards)+'</ol></section>'
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">{CSS}</head><body><main>{body}</main></body></html>'

